#!/usr/bin/env python3
"""8д (B2): доп. KPI фермы по логам плеера — доля источников дохода по главам (комбо, герой, лента, пушка, Спортзал), выплаты комбо
(число, средняя и наибольшая серия, закрытые на 60, источник), звук подбора (ступень, высота, голоса, ступень после броска), коробки
(в Яму, раскрыто), посылка ждёт героя. Только stdlib.
usage: python3 -I b2_kpi.py <out.md> <label>=<dir> [<label>=<dir> ...]
"""
import os, re, sys, glob, statistics as S

GROUPS = (('nb_', 'Новичок'), ('nbrv_', 'Новичок + ролики'), ('c1_', 'Бот'), ('ch2_', 'Глава II после «Пропустить»'))
KV = re.compile(r'(\w+)=(-?[\d.]+)')
SRC = ('hero', 'belt', 'cannon', 'combo', 'gym', 'fans', 'orders', 'gift', 'crates', 'total')


def kv(s):
    return {k: float(v) for k, v in KV.findall(s)}


def parse(path):
    r = dict(inc={}, pays={1: [], 2: []}, sfx=[], crate_pit=0, crate_open=0, gift_hold=0, gift_expire=0, ch2_t=None, skip=0, err=0)
    ch = 1
    for line in open(path, encoding='utf-8', errors='replace'):
        if line.startswith(('NullReferenceException', 'IndexOutOfRangeException', 'ArgumentOutOfRangeException', 'InvalidOperationException')):
            r['err'] += 1
        if not line.startswith('[PITT] [onepit] '):
            continue
        s = line[16:].rstrip('\n')
        if s.startswith('norm chapter ch='):
            ch = int(re.search(r'ch=(\d+)', s).group(1))
            if ch == 2 and r['ch2_t'] is None:
                r['ch2_t'] = float(re.search(r' t=([\d.]+)', s).group(1))
        elif s.startswith('income hero='):
            m = re.search(r' ch=(\d+)$', s)
            c = int(m.group(1)) if m else ch
            d = r['inc'].setdefault(c, dict((k, 0.0) for k in SRC))
            for k, v in kv(s).items():
                if k in d:
                    d[k] += v
        elif s.startswith('combo pay '):
            d = kv(s); d['src'] = (re.search(r'src=(\w+)', s) or [None, 'hero'])[1] if 'src=' in s else 'hero'
            r['pays'].setdefault(ch, []).append(d)
        elif s.startswith('sfx sum '):
            r['sfx'].append(kv(s))
        elif s.startswith('crate pit rise') or s.startswith('crate pit open'):
            r['crate_pit'] += 1
        elif s.startswith('crate open '):
            r['crate_open'] += 1
        elif s.startswith('rv hold n='):
            r['gift_hold'] += 1
        elif s.startswith('rv expire '):
            r['gift_expire'] += 1
        elif s.startswith('skip ch=1->'):
            r['skip'] += 1
    return r


def agg(xs):
    xs = [x for x in xs if x is not None]
    if not xs:
        return '—'
    m = S.mean(xs)
    f = (lambda v: f'{v:.1f}'.replace('.', ',')) if abs(m) < 1000 else (lambda v: f'{v:,.0f}'.replace(',', ' '))
    return f'{f(m)} [{f(min(xs))}…{f(max(xs))}] n{len(xs)}'


def kpi(r):
    o = {}
    for c in (1, 2):
        d = r['inc'].get(c)
        if d and d['total'] > 0:
            for k in ('hero', 'belt', 'cannon', 'combo', 'gym'):
                o[f'share_{k}_ch{c}'] = 100.0 * d[k] / d['total']
        p = r['pays'].get(c) or []
        o[f'combo_pays_ch{c}'] = len(p)
        o[f'combo_n_mean_ch{c}'] = S.mean([x['n'] for x in p]) if p else None
        o[f'combo_n_max_ch{c}'] = max([x['n'] for x in p]) if p else None
        o[f'combo_max60_ch{c}'] = sum(1 for x in p if x.get('max') == 1)
        o[f'combo_bumper_pays_ch{c}'] = sum(1 for x in p if x.get('src') == 'bumper')
        o[f'combo_frac_mean_ch{c}'] = S.mean([x['frac'] for x in p]) if p else None
    if r['sfx']:
        o['sfx_step_max'] = max(x.get('step_max', 0) for x in r['sfx'])
        o['sfx_pitch_max'] = max(x.get('pitch_max', 0) for x in r['sfx'])
        o['sfx_voices_max'] = max(x.get('voices_max', 0) for x in r['sfx'])
        o['sfx_after_reset_max'] = max(x.get('after_reset_max', -1) for x in r['sfx'])
